'use strict';
const $=(s)=>document.querySelector(s),$$=(s)=>Array.from(document.querySelectorAll(s));
const stories=[
{title:'A garden promise',category:'Weddings',image:'wedding',alt:'A bride and groom holding hands between sculpted garden hedges',credit:'Christophe Dusabe',source:'https://unsplash.com/photos/a-man-and-woman-kissing-ay1PL5MgFx0'},
{title:'A world of our own',category:'Couples',image:'landscape',alt:'A couple kissing in a wildflower meadow above the mountains',credit:'pai pai',source:'https://unsplash.com/photos/a-couple-holding-hands-walking-in-a-grassy-field-Uil4bmA_zwE'},
{title:'A quiet kind of presence',category:'Portraits',image:'portrait',alt:'A bride in an intricate white wedding gown, framed by her veil',credit:'Steward Masweneng',source:'https://unsplash.com/pt-br/fotografias/mulher-no-vestido-de-noiva-branco-que-esta-na-frente-do-espelho-YxKe2Uar9PI'},
{title:'Closer, still',category:'Couples',image:'embrace',alt:'A groom kissing the forehead of his bride in a tropical garden',credit:'Unsplash contributor',source:'https://unsplash.com/s/photos/vintage-wedding'},
{title:'All the little feelings',category:'Weddings',image:'kiss',alt:'A newlywed couple sharing a kiss beside a white wall',credit:'Unsplash contributor',source:'https://unsplash.com/fr/s/photos/mariage-couple-noir'},
{title:'In her own light',category:'Portraits',image:'bride',alt:'A bride with eyes closed, holding a bouquet in natural light',credit:'Brayden Prato',source:'https://unsplash.com/photos/a-woman-in-a-wedding-dress-holding-a-bouquet-of-flowers-rJwHccMGDLI'}
];
let activeFilter='All',visibleStories=stories.slice(),activePhoto=0,galleryTrigger=null;
function renderWork(filter='All'){activeFilter=filter;visibleStories=stories.filter(s=>filter==='All'||s.category===filter);$('#workGrid').classList.toggle('filtered',filter!=='All');$('#workGrid').innerHTML=visibleStories.map((s,i)=>`<button class="work-card" data-story="${i}" aria-label="Open ${s.title}, ${s.category} photograph"><div class="work-photo"><img src="assets/${s.image}.jpg" alt="${s.alt}" loading="lazy" width="1000" height="1250"><span class="view-label">View photograph <b>↗</b></span></div><div class="work-card-meta"><div><h3>${s.title}</h3><p>${s.category}　 /　 Visual study</p></div><span>${String(stories.indexOf(s)+1).padStart(2,'0')} ↗</span></div></button>`).join('');$('#workCount').textContent=`Showing ${visibleStories.length} visual ${visibleStories.length===1?'story':'stories'}`;$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))})}
function showPhoto(){const s=visibleStories[activePhoto];$('#viewerImage').src=`assets/${s.image}.jpg`;$('#viewerImage').alt=s.alt;$('#viewerTitle').textContent=s.title;$('#viewerCounter').textContent=`${String(activePhoto+1).padStart(2,'0')} / ${String(visibleStories.length).padStart(2,'0')}`;$('#viewerCredit').innerHTML=`Sample photograph · <a href="${s.source}" target="_blank" rel="noopener">${s.credit} / Unsplash ↗</a>`}
function openGallery(i,trigger){activePhoto=i;galleryTrigger=trigger;showPhoto();$('#viewer').showModal();document.body.classList.add('locked')}
function closeGallery(){$('#viewer').close();document.body.classList.remove('locked');galleryTrigger?.focus()}
$('#nextPhoto').onclick=()=>{activePhoto=(activePhoto+1)%visibleStories.length;showPhoto()};$('#previousPhoto').onclick=()=>{activePhoto=(activePhoto-1+visibleStories.length)%visibleStories.length;showPhoto()};$('.viewer-close').onclick=closeGallery;$('#viewer').addEventListener('cancel',()=>document.body.classList.remove('locked'));$('#viewer').addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();$('#nextPhoto').click()}if(e.key==='ArrowLeft'){e.preventDefault();$('#previousPhoto').click()}});
function toggleMenu(force){const open=typeof force==='boolean'?force:$('#menuToggle').getAttribute('aria-expanded')!=='true';$('#menuToggle').setAttribute('aria-expanded',String(open));$('#menu').hidden=!open;$('#menuToggle').setAttribute('aria-label',open?'Close menu':'Open menu')}$('#menuToggle').onclick=()=>toggleMenu();document.addEventListener('keydown',e=>{if(e.key==='Escape')toggleMenu(false)});document.addEventListener('click',e=>{if(!e.target.closest('#menu')&&!e.target.closest('#menuToggle'))toggleMenu(false)});$$('#menu a').forEach(a=>a.addEventListener('click',()=>toggleMenu(false)));
const serviceData=[{image:'wedding',alt:'A bride and groom holding hands in a garden',caption:'The celebration. And everything in between.'},{image:'landscape',alt:'A couple surrounded by a mountain meadow',caption:'A place. A feeling. Just the two of you.'},{image:'portrait',alt:'A bride in a considered editorial portrait',caption:'An honest portrait. A considered perspective.'}];function selectService(i){$$('.service').forEach((a,n)=>{const open=i===n;a.classList.toggle('open',open);a.querySelector('button').setAttribute('aria-expanded',String(open));a.querySelector('button>b').textContent=open?'−':'+';a.querySelector('.service-body').hidden=!open});$('#serviceImage').src=`assets/${serviceData[i].image}.jpg`;$('#serviceImage').alt=serviceData[i].alt;$('#serviceCaption').textContent=serviceData[i].caption;$('#serviceNumber').textContent=`0${i+1} / 03`}
function info(html){$('#infoContent').innerHTML=html;$('#infoDialog').showModal();document.body.classList.add('locked')}function closeInfo(){$('#infoDialog').close();document.body.classList.remove('locked')}$('.info-close').onclick=closeInfo;$('#infoDialog').addEventListener('cancel',()=>document.body.classList.remove('locked'));$('#infoDialog').addEventListener('click',e=>{if(e.target===$('#infoDialog'))closeInfo()});
function credits(){info(`<div class="eyebrow">A note on the imagery</div><h2>Good work deserves<br>its own credit.</h2><p>This is a design preview for Ori Pictures. The sample photographs below belong to their respective photographers and are not presented as Ori Pictures client work. The visual collection will be replaced with the studio’s original portfolio.</p>${stories.map(s=>`<div class="credit-row"><a href="${s.source}" target="_blank" rel="noopener">${s.title} ↗</a><span>${s.credit} · Unsplash</span></div>`).join('')}<div class="credit-row"><a href="https://unsplash.com/photos/a-man-and-woman-posing-for-a-picture-LByCUYDAt4M" target="_blank" rel="noopener">Garden image in the philosophy chapter ↗</a><span>Christophe Dusabe · Unsplash</span></div>`)}$('#creditsOpen').onclick=$('#creditsFooter').onclick=credits;
$('#privacyOpen').onclick=()=>info('<div class="eyebrow">Privacy & enquiries</div><h2>Your story is yours.</h2><p>The enquiry form prepares a message addressed to info@oripictures.com. You can review the details, then choose to open your email app and send it yourself. This site does not send your enquiry automatically or store its contents in browser storage. You can also download a private copy.</p><p>Sample images and typefaces are used in this design preview. Typeface loading may contact Google Fonts. No analytics, advertising trackers, payments, or account registration have been added.</p><p>A booking is only confirmed after the studio has agreed the scope, availability, and terms directly with you.</p>');
const articles=[{tag:'Planning',title:'Making space for the moments you’ll want to remember.',lead:'The best photographs often happen in the space between the plans.',sections:[['Leave a little room.','A timeline gives the day shape, but it doesn’t need to fill every minute. Small pauses let you take in the people around you and give real moments a chance to unfold.'],['Choose what matters to you.','A long list of reference pictures can pull you out of your own celebration. Start with a few priorities: the people you want together, any meaningful traditions, and the moments you would love to relive.'],['Think about the light.','If photographs are important to you, discuss the light at your venue early. A little flexibility around the timing of a portrait can make space for something beautiful without taking over your day.'],['Come back to the people.','The flowers, setting, and details tell part of the story. The way your people look at you tells another. Give yourself permission to be with them.']]},{tag:'In front of the lens',title:'You don’t have to know what to do with your hands.',lead:'Feeling a little awkward is a perfectly good place to begin.',sections:[['Start with movement.','A short walk, a change of direction, or leaning into someone you love is often more comfortable than holding a pose. Simple actions give your attention somewhere natural to go.'],['Wear something that feels like you.','Comfort shows up in photographs. Choose clothes you can move in, and a setting where you feel at ease. Bring a layer or a second option if that helps you settle in.'],['Let the conversation happen.','You don’t have to look at the camera the whole time. Talk to each other, take a breath, or notice what is around you. The in-between expressions are part of the story.'],['Trust the gentle direction.','A portrait can be intentional without becoming a performance. A few small adjustments to light, position, or movement are enough. The personality is already yours.']]}];
function article(i){const a=articles[i];info(`<div class="eyebrow">Notes for the journey / ${a.tag}</div><h2>${a.title}</h2><p class="article-lead">${a.lead}</p>${a.sections.map(s=>`<h3>${s[0]}</h3><p>${s[1]}</p>`).join('')}<a href="#inquire" id="articleEnquire" class="round-button">Let’s plan your story <span>↗</span></a>`);$('#articleEnquire').onclick=closeInfo}
document.addEventListener('click',e=>{const f=e.target.closest('[data-filter]');if(f)renderWork(f.dataset.filter);const s=e.target.closest('[data-story]');if(s)openGallery(+s.dataset.story,s);const service=e.target.closest('[data-service]');if(service)selectService(+service.dataset.service);const interest=e.target.closest('[data-interest]');if(interest)$('#interest').value=interest.dataset.interest;const a=e.target.closest('[data-article]');if(a)article(+a.dataset.article)});
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let draftText='';function downloadDraft(){const blob=new Blob([draftText],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Ori-Pictures-Enquiry.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('#enquiryForm').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));draftText=`ORI PICTURES — ENQUIRY DRAFT\n\nName: ${data.name}\nEmail: ${data.email}\nPhotography: ${data.service}\nDate: ${data.date||'To be decided'}\nLocation: ${data.location||'To be decided'}\n\n${data.message}\n\nThis is a draft. It has not been sent and does not confirm a booking.\n`;info(`<div class="eyebrow">Your next chapter</div><h2>Your enquiry,<br>ready to share.</h2><p>Your message is ready for info@oripictures.com. Open your email app to review and send it. Nothing has been sent yet.</p><pre>${escapeHTML(draftText)}</pre><div class="enquiry-actions"><a class="round-button" id="emailEnquiry">Open email app <span>↗</span></a><button class="round-button" id="downloadDraft">Download a copy <span>↓</span></button></div><p class="email-fallback">Prefer to write directly? <a href="mailto:info@oripictures.com">info@oripictures.com</a></p>`);$('#emailEnquiry').href='mailto:info@oripictures.com?subject='+encodeURIComponent('Photography enquiry — '+data.service+' — '+data.name)+'&body='+encodeURIComponent(draftText.replace('This is a draft. It has not been sent and does not confirm a booking.',''));$('#downloadDraft').onclick=()=>{downloadDraft();$('#formFeedback').textContent='Enquiry draft downloaded. Nothing has been submitted online.'}});
const date=$('input[name=date]');date.min=new Date().toLocaleDateString('en-CA');$('#year').textContent=new Date().getFullYear();renderWork();

/* Menu icon: white over photos and dark sections, ink over light ones */
(function(){const t=$('#menuToggle');let q=false;function tone(){q=false;const r=t.getBoundingClientRect();const x=r.left+r.width/2,y=r.top+r.height/2;let dark=true;for(const el of document.elementsFromPoint(x,y)){if(t.contains(el))continue;if(el.tagName==='IMG'){dark=true;break}const c=getComputedStyle(el).backgroundColor.match(/[\d.]+/g);if(c&&(c.length<4||+c[3]>.5)){dark=(.2126*c[0]+.7152*c[1]+.0722*c[2])<140;break}}t.classList.toggle('on-light',!dark)}function ask(){if(!q){q=true;requestAnimationFrame(tone)}}addEventListener('scroll',ask,{passive:true});addEventListener('resize',ask);t.addEventListener('click',ask);ask()})();
